namespace local_visudesk\external;

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_single_structure;
use core_external\external_value;
use local_visudesk\local\vgstore;

/**
 * VisuGrade sync: deletes changes up to a number that the snapshot covers (deletion period).
 *
 * @package    local_visudesk
 * @copyright  2026 Holger Sebastião
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class vg_purge extends external_api {
    /**
     * Parameters.
     *
     * @return external_function_parameters
     */
    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'upto' => new external_value(PARAM_INT, 'Delete changes up to this number'),
        ]);
    }

    /**
     * Runs the function for the calling user only.
     *
     * @param int $upto
     * @return array
     */
    public static function execute(int $upto): array {
        global $USER;
        $params = self::validate_parameters(self::execute_parameters(), ['upto' => $upto]);
        get_plan::check_user();
        return ['deleted' => vgstore::purge((int)$USER->id, $params['upto'])];
    }

    /**
     * Return structure.
     *
     * @return external_single_structure
     */
    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'deleted' => new external_value(PARAM_INT, 'Deleted changes'),
        ]);
    }
}
